/** Filename shapes generated by NovelAI or storage tools, never a length heuristic. */
export function isUnnamedImage(name) {
  const stem = String(name || '').replace(/\.(png|jpe?g|webp|gif|avif|bmp|tiff?)$/i, '');
  return (
    /s-\d+(?: \(\d+\))?$/.test(stem) ||
    /^[a-f\d]{16,}$/i.test(stem) ||
    /^[a-f\d]{8}(?:-[a-f\d]{4}){3}-[a-f\d]{12}$/i.test(stem)
  );
}

export function hasImageName(image) {
  return image.has_custom_name === true || !isUnnamedImage(image.name);
}

export function imageFileName(image) {
  if (image.original_filename) return image.original_filename;
  const extension = String(image.image_path || '').match(/\.[^.\\/]+$/)?.[0] || '.png';
  const name = String(image.name || '');
  return /\.(png|jpe?g|webp|gif|avif|bmp|tiff?)$/i.test(name) ? name : name + extension;
}

export function numberedImageNames(name, count) {
  const base = name.trim();
  const digits = Math.max(2, String(count).length);
  return Array.from({ length: count }, (_, i) =>
    count === 1 ? base : `${base}-${String(i + 1).padStart(digits, '0')}`,
  );
}

export function imageAccessibleName(image) {
  if (hasImageName(image)) return image.name;
  const date = new Date(image.created_at);
  return `图片，导入于 ${date.getMonth() + 1} 月 ${date.getDate()} 日 ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}
